:root {
  --bg: #040404;
  --surface: #0f0f0f;
  --surface-soft: rgba(255, 255, 255, 0.08);
  --ink: #ffffff;
  --ink-muted: rgba(255, 255, 255, 0.74);
  --line: rgba(255, 255, 255, 0.2);
  --primary: #f15922;
  --primary-strong: #f15922;
  --accent: #fea12a;
  --accent-soft: rgba(254, 161, 42, 0.16);
  --success: #11825f;
  --tone-alert: #cf461c;
  --tone-alert-soft: rgba(207, 70, 28, 0.18);
  --tone-warning: #f5c73b;
  --tone-warning-soft: rgba(245, 199, 59, 0.17);
  --tone-info: #8b6542;
  --tone-info-soft: rgba(139, 101, 66, 0.16);
  --tone-success: #9ca56e;
  --tone-success-soft: rgba(156, 165, 110, 0.16);
  --tone-neutral: #6e5440;
  --tone-neutral-soft: rgba(110, 84, 64, 0.14);
  --radius-sm: 14px;
  --radius-md: 22px;
  --radius-lg: 30px;
  --shadow-sm: 0 10px 26px rgba(0, 0, 0, 0.45);
  --shadow-md: 0 22px 48px rgba(0, 0, 0, 0.54);
  --site-width: min(1320px, 97vw);
  --site-pad: 1.15rem;
}

body[data-live-dashboard][data-account-page="clients"] .admin-account-records-layout {
  gap: 1.15rem;
  align-items: start;
}

body[data-live-dashboard][data-account-page="clients"] .admin-account-records-layout > .card {
  min-width: 0;
}

body[data-live-dashboard][data-account-page="clients"] .admin-account-record-panel-grid {
  display: grid;
  gap: 1rem;
}

body[data-live-dashboard][data-account-page="clients"] .admin-account-record-panel {
  display: grid;
  gap: 0.85rem;
  padding: 1rem 1.05rem;
  border-radius: 18px;
  border: 1px solid rgba(255, 207, 152, 0.14);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.024), rgba(255, 255, 255, 0)),
    rgba(16, 12, 10, 0.8);
  box-shadow:
    inset 0 1px 0 rgba(255, 255, 255, 0.03),
    0 20px 44px rgba(0, 0, 0, 0.18);
}

body[data-live-dashboard][data-account-page="clients"] .admin-account-record-panel h4,
body[data-live-dashboard][data-account-page="clients"] .admin-account-record-signature h4 {
  margin: 0;
  font-size: 0.9rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: rgba(255, 188, 116, 0.92);
}

body[data-live-dashboard][data-account-page="clients"] .admin-account-record-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 0.85rem;
  min-width: 0;
}

body[data-live-dashboard][data-account-page="clients"] .admin-account-record-field {
  display: grid;
  gap: 0.3rem;
  min-height: 100%;
  min-width: 0;
  padding: 0.9rem 0.95rem;
  border-radius: 16px;
  border: 1px solid rgba(255, 207, 152, 0.12);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.024), rgba(255, 255, 255, 0)),
    rgba(8, 6, 5, 0.82);
}

body[data-live-dashboard][data-account-page="clients"] .admin-account-record-field span {
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: rgba(255, 205, 162, 0.7);
}

body[data-live-dashboard][data-account-page="clients"] .admin-account-record-field strong {
  font-size: 0.96rem;
  line-height: 1.45;
  color: rgba(255, 245, 232, 0.94);
  overflow-wrap: anywhere;
  word-break: break-word;
  hyphens: auto;
}

body[data-live-dashboard][data-account-page="clients"] #admin-account-record-summary {
  min-width: 0;
  overflow-wrap: anywhere;
  word-break: break-word;
}

body[data-live-dashboard][data-account-page="clients"] #admin-account-record-summary small {
  display: block;
  margin-top: 0.35rem;
  line-height: 1.5;
  color: rgba(242, 224, 201, 0.78);
  overflow-wrap: anywhere;
  word-break: break-word;
}

body[data-live-dashboard][data-account-page="clients"] #admin-account-record-filter-form {
  display: grid;
  gap: 0.95rem;
}

body[data-live-dashboard][data-account-page="clients"] #admin-account-record-filter-form .input-row {
  align-items: end;
}

body[data-live-dashboard][data-account-page="clients"] #admin-account-record-filter-form label,
body[data-live-dashboard][data-account-page="clients"] #admin-account-record-filter-form select {
  min-width: 0;
}

body[data-live-dashboard][data-account-page="clients"] #admin-account-records .section-actions--compact {
  align-items: stretch;
}

body[data-live-dashboard][data-account-page="clients"] #admin-account-records .section-actions--compact .btn {
