.coach-training-template-library {
  display: grid;
  gap: 0.9rem;
}

.coach-training-template-library .coach-programming-template-card {
  gap: 0.85rem;
}

.coach-programming-template-card__notes {
  display: grid;
  gap: 0.35rem;
}

.coach-programming-template-card__notes p {
  margin: 0;
  color: rgba(255, 244, 228, 0.72);
  font-size: 0.92rem;
}

.coach-training-calendar-toolbar-card {
  margin-block: 1.1rem 1rem;
}

.client-planner-execution-note {
  display: block;
  margin-top: 0.45rem;
  color: rgba(255, 211, 150, 0.84);
}

@media (max-width: 1180px) {
  .coach-training-sheet-grid,
  .coach-training-sheet-grid--assignment {
    grid-template-columns: 1fr;
  }

  .coach-training-page-meta {
    max-width: none;
  }

  .coach-training-exercise-row__meta,
  .coach-training-day-grid,
  .coach-training-day-grid--advanced {
