  position: relative;
  isolation: isolate;
  overflow: hidden;
  width: 100%;
  min-height: 332px;
  display: grid;
  align-content: start;
  gap: 1rem;
  padding: 1.4rem 1.45rem 1.35rem;
  border: 1px solid var(--mode-border);
  border-radius: 32px;
  background:
    linear-gradient(
      152deg,
      rgba(255, 255, 255, 0.08),
      rgba(var(--mode-accent-alt), 0.09) 16%,
      rgba(var(--mode-accent), 0.04) 40%,
      rgba(8, 8, 8, 0.97)
