.coach-schedule-header-day {
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(var(--coach-schedule-spectrum-rgb, var(--coach-schedule-accent-rgb)), 0.92);
}

.coach-schedule-header-date {
  margin-top: 0.18rem;
  font-size: 0.82rem;
  font-weight: 600;
  letter-spacing: 0.01em;
  color: rgba(255, 248, 236, 0.74);
}

.coach-schedule-time-rail {
  position: sticky;
  left: 0;
  z-index: 3;
  min-height: calc(var(--coach-schedule-hours) * var(--coach-schedule-hour-size));
  border-right: 1px solid rgba(var(--coach-schedule-accent-rgb), 0.12);
  background:
    repeating-linear-gradient(
      to bottom,
      rgba(255, 255, 255, 0.08) 0,
      rgba(255, 255, 255, 0.08) 1px,
      transparent 1px,
      transparent var(--coach-schedule-hour-size)
    ),
    linear-gradient(
      180deg,
      rgba(var(--coach-schedule-spectrum-rgb, var(--coach-schedule-accent-rgb)), 0.08),
      rgba(9, 9, 9, 0.96)
    );
}

.coach-schedule-time-label {
  position: absolute;
  left: 50%;
  width: calc(100% - 0.5rem);
  padding-inline: 0.2rem;
  display: flex;
  align-items: center;
  justify-content: center;
  text-align: center;
  transform: translate(-50%, -50%);
  font-size: 0.69rem;
  font-weight: 700;
  letter-spacing: 0.06em;
  color: rgba(255, 245, 234, 0.62);
}

.coach-schedule-time-label.is-terminal {
  transform: translate(-50%, -100%);
}

.coach-schedule-board {
  display: grid;
  grid-template-columns: repeat(7, minmax(120px, 1fr));
  min-height: calc(var(--coach-schedule-hours) * var(--coach-schedule-hour-size));
}

.coach-schedule-board-day {
  position: relative;
  min-height: calc(var(--coach-schedule-hours) * var(--coach-schedule-hour-size));
  background:
    repeating-linear-gradient(
      to bottom,
      rgba(255, 255, 255, 0.08) 0,
      rgba(255, 255, 255, 0.08) 1px,
      transparent 1px,
      transparent var(--coach-schedule-hour-size)
    ),
    linear-gradient(
      180deg,
      rgba(var(--coach-schedule-accent-rgb), 0.04),
      rgba(var(--coach-schedule-spectrum-rgb, var(--coach-schedule-accent-rgb)), 0.02) 34%,
      rgba(5, 5, 5, 0.12)
    );
}

.coach-schedule-board-day + .coach-schedule-board-day {
  border-left: 1px solid rgba(var(--coach-schedule-accent-rgb), 0.1);
}

.coach-schedule-day-state {
  position: absolute;
  top: 1rem;
  left: 50%;
  transform: translateX(-50%);
  padding: 0.35rem 0.72rem;
  border-radius: 999px;
  border: 1px dashed rgba(var(--coach-schedule-accent-rgb), 0.18);
  background: rgba(var(--coach-schedule-spectrum-rgb, var(--coach-schedule-accent-rgb)), 0.08);
  color: rgba(255, 255, 255, 0.52);
  font-size: 0.68rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.coach-schedule-slot {
  position: absolute;
  left: 0.42rem;
  right: 0.42rem;
  display: grid;
  align-content: center;
  justify-items: center;
  gap: 0;
  min-height: 48px;
  padding: 0.58rem 0.62rem;
  border-radius: 14px;
  border: 1px solid rgba(var(--coach-schedule-accent-rgb), 0.34);
  background:
    linear-gradient(180deg, rgba(var(--coach-schedule-accent-rgb), 0.28), rgba(var(--coach-schedule-accent-rgb), 0.14)),
    linear-gradient(180deg, rgba(255, 255, 255, 0.09), rgba(24, 24, 24, 0.2));
  color: var(--coach-schedule-accent);
  text-align: center;
  cursor: pointer;
  box-shadow:
    0 16px 26px rgba(0, 0, 0, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
  transition: transform 0.18s ease, filter 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease;
}

.coach-schedule-slot:hover,
.coach-schedule-slot:focus-visible {
  transform: translateY(-1px) scale(1.01);
  filter: brightness(1.16);
  border-color: rgba(var(--coach-schedule-accent-rgb), 0.6);
  box-shadow:
    0 16px 30px rgba(0, 0, 0, 0.3),
    0 0 0 1px rgba(var(--coach-schedule-accent-rgb), 0.18),
    0 0 18px rgba(var(--coach-schedule-accent-rgb), 0.16);
  outline: none;
}

.coach-schedule-slot.is-busy:hover,
.coach-schedule-slot.is-busy:focus-visible {
  transform: none;
  filter: saturate(0.78);
  border-color: rgba(255, 255, 255, 0.14);
  box-shadow:
    0 12px 22px rgba(0, 0, 0, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.coach-schedule-slot-status {
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: rgba(255, 242, 226, 0.76);
}

.coach-schedule-slot.is-busy {
  border-color: rgba(255, 255, 255, 0.14);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.08), rgba(255, 255, 255, 0.03)),
    linear-gradient(180deg, rgba(18, 18, 18, 0.96), rgba(5, 5, 5, 0.98));
  color: rgba(255, 255, 255, 0.76);
  box-shadow:
    0 12px 22px rgba(0, 0, 0, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);
  cursor: not-allowed;
  filter: saturate(0.78);
}

.coach-schedule-slot.is-busy .coach-schedule-slot-status {
  color: rgba(255, 255, 255, 0.74);
}

.coach-schedule-empty {
  margin: 0;
  padding: 1rem 1.1rem;
  border: 1px dashed rgba(var(--coach-schedule-accent-rgb), 0.18);
  border-radius: 18px;
  background:
    linear-gradient(
      180deg,
      rgba(var(--coach-schedule-spectrum-rgb, var(--coach-schedule-accent-rgb)), 0.08),
      rgba(0, 0, 0, 0.18)
    );
  color: rgba(255, 245, 234, 0.76);
}

.coach-schedule-note {
  margin-top: 0.9rem;
  color: rgba(255, 249, 241, 0.78);
}

.coach-schedule-panel .section-actions {
  margin-top: 1rem;
  position: relative;
  z-index: 8;
  flex: 0 0 auto;
  padding-top: 0.95rem;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
  background:
    linear-gradient(180deg, rgba(7, 7, 7, 0), rgba(7, 7, 7, 0.92) 18%, rgba(7, 7, 7, 0.98)),
    linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0));
}

.coach-schedule-panel .btn-primary {
  border-color: rgba(var(--coach-schedule-accent-rgb), 0.66);
  background: linear-gradient(140deg, var(--coach-schedule-accent), rgba(var(--coach-schedule-accent-rgb), 0.72));
  color: var(--coach-schedule-accent-ink);
  box-shadow:
    0 14px 28px rgba(0, 0, 0, 0.42),
    0 0 0 1px rgba(var(--coach-schedule-accent-rgb), 0.42),
    0 0 22px rgba(var(--coach-schedule-accent-rgb), 0.26),
    inset 0 1px 0 rgba(255, 255, 255, 0.24),
    inset 0 -5px 10px rgba(0, 0, 0, 0.12);
}

.coach-schedule-panel .btn-primary::before {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.16), transparent 44%);
}

.coach-schedule-panel .btn-primary::after {
  background:
    linear-gradient(90deg, rgba(255, 255, 255, 0.14), transparent 16%, transparent 84%, rgba(255, 255, 255, 0.14));
}

.coach-schedule-panel .btn-primary:hover {
  border-color: rgba(var(--coach-schedule-accent-rgb), 0.78);
  box-shadow:
    0 18px 34px rgba(0, 0, 0, 0.45),
    0 0 0 1px rgba(var(--coach-schedule-accent-rgb), 0.5),
    0 0 28px rgba(var(--coach-schedule-accent-rgb), 0.34),
    inset 0 1px 0 rgba(255, 255, 255, 0.28),
    inset 0 -7px 13px rgba(0, 0, 0, 0.14);
}

.coach-schedule-panel .btn-ghost {
  border-color: rgba(var(--coach-schedule-accent-rgb), 0.4);
  color: var(--coach-schedule-accent);
  background:
    linear-gradient(180deg, rgba(var(--coach-schedule-accent-rgb), 0.16), rgba(var(--coach-schedule-accent-rgb), 0.08)),
    linear-gradient(180deg, rgba(15, 15, 15, 0.96), rgba(6, 6, 6, 0.96));
  box-shadow:
    0 14px 24px rgba(0, 0, 0, 0.3),
    0 0 0 1px rgba(var(--coach-schedule-accent-rgb), 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.coach-schedule-panel .btn-ghost::before {
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.06), transparent 44%);
}

.coach-schedule-panel .btn-ghost::after {
  background:
    linear-gradient(90deg, rgba(var(--coach-schedule-accent-rgb), 0.12), transparent 16%, transparent 84%, rgba(var(--coach-schedule-accent-rgb), 0.12));
}

.coach-schedule-panel .btn-ghost:hover {
  border-color: rgba(var(--coach-schedule-accent-rgb), 0.56);
  box-shadow:
    0 18px 30px rgba(0, 0, 0, 0.34),
    0 0 0 1px rgba(var(--coach-schedule-accent-rgb), 0.14),
    0 0 20px rgba(var(--coach-schedule-accent-rgb), 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.12);
}

.team-selection-banner {
  position: relative;
  overflow: hidden;
  width: 100vw;
  margin: clamp(1.4rem, 4vw, 2.4rem) calc(50% - 50vw) 0;
  min-height: clamp(30rem, 56vw, 46rem);
  display: grid;
  place-items: start center;
  padding: clamp(3.2rem, 7vw, 5.2rem) var(--site-pad) clamp(8rem, 18vw, 12rem);
  background:
    linear-gradient(180deg, rgba(4, 4, 4, 0.04), rgba(4, 4, 4, 0.16)),
    var(--surface);
}

.team-selection-art {
  position: absolute;
  inset: 0;
  z-index: 0;
  overflow: hidden;
}

.team-selection-art img {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: 50% 58%;
  transform: none;
  display: block;
}

.team-selection-banner::before {
  content: "";
  position: absolute;
  inset: 0;
  background:
    linear-gradient(
      180deg,
      rgba(4, 4, 4, 0.34) 0%,
      rgba(4, 4, 4, 0.18) 26%,
      rgba(5, 5, 5, 0.22) 58%,
      rgba(8, 8, 8, 0.52) 100%
    ),
    linear-gradient(
      90deg,
      rgba(4, 4, 4, 0.42) 0%,
      rgba(4, 4, 4, 0.1) 24%,
      rgba(4, 4, 4, 0.08) 76%,
      rgba(4, 4, 4, 0.36) 100%
    );
  z-index: 0;
  pointer-events: none;
}

.team-selection-banner::after {
  content: "";
  position: absolute;
  inset: 0;
  background:
    radial-gradient(46rem 18rem at 50% 82%, rgba(255, 255, 255, 0.06), transparent 72%),
    radial-gradient(36rem 16rem at 16% 18%, rgba(255, 255, 255, 0.03), transparent 72%),
    radial-gradient(36rem 16rem at 84% 18%, rgba(255, 255, 255, 0.03), transparent 72%);
  mix-blend-mode: screen;
  opacity: 0.38;
  z-index: 0;
  pointer-events: none;
}

.team-selection-copy {
  position: relative;
  z-index: 1;
  display: grid;
  justify-items: center;
  text-align: center;
  width: min(82rem, 100%);
  align-content: start;
  padding-top: clamp(0.4rem, 2vw, 1.2rem);
}

.team-selection-banner h2 {
  width: auto;
  max-width: none;
  margin: 0;
  font-family: "League Spartan", "Segoe UI", sans-serif;
  font-size: clamp(3rem, 6.4vw, 5.45rem);
  line-height: 0.92;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  white-space: nowrap;
  color: #ffffff;
  text-shadow: 0 8px 34px rgba(0, 0, 0, 0.7);
}

.team-selection-banner h2 .title-highlight {
  display: inline-block;
  background: linear-gradient(140deg, var(--primary), var(--accent));
  -webkit-background-clip: text;
  background-clip: text;
  -webkit-text-fill-color: transparent;
  color: var(--accent);
  filter: saturate(1.12) brightness(1.12);
  text-shadow: none;
}

.team-selection-legacy {
  margin: 0.95rem 0 0;
  width: 100%;
  text-align: center;
  font-size: 1rem;
  letter-spacing: 0.22em;
  text-transform: uppercase;
  color: rgba(255, 255, 255, 0.46);
  text-shadow: 0 8px 22px rgba(0, 0, 0, 0.44);
}

.team-selection-banner .section-actions {
  margin-top: 1.3rem;
  justify-content: center;
}

.coach-detail-hero {
  display: grid;
  gap: 0.72rem;
}

.coach-detail-hero h1 {
  max-width: 12ch;
  margin: 0;
  font-size: clamp(3.7rem, 11vw, 7.2rem);
  line-height: 0.9;
  letter-spacing: -0.03em;
  margin-top: 0.16rem;
}

.coach-detail-hero .kicker {
  margin: 0;
  line-height: 1;
}

.coach-detail-hero p {
  max-width: 60ch;
  margin: 0;
  margin-top: 0.2rem;
  line-height: 1.5;
}

.coach-gallery-section {
  gap: 1rem;
  margin-top: 1.8rem;
}

.coach-gallery-section > h2 {
  display: none;
}

.coach-detail-grid {
  display: grid;
  gap: 1.05rem;
}

.coach-detail-card {
  min-width: 0;
  padding: clamp(1.35rem, 2.6vw, 1.7rem);
}

.coach-detail-card h2 {
  margin: 0;
  font-size: 1.1rem;
}

.coach-detail-card p {
  margin-top: 0.55rem;
  max-width: 62ch;
  color: var(--ink-muted);
}

.coach-detail-card p + p {
  margin-top: 0.95rem;
}

.coach-persona-section {
  gap: 1.1rem;
  margin-top: 1.8rem;
}

.coach-persona-grid {
  display: grid;
  gap: 1rem;
}

.coach-persona-card {
  min-width: 0;
}

.coach-persona-card h3 {
  margin: 0;
}

.coach-persona-card p {
  margin-top: 0.42rem;
  color: var(--ink-muted);
}

.coach-style-section {
  display: block;
  margin-top: 1.8rem;
}

.coach-style-grid {
  display: grid;
  gap: 1.45rem;
  align-items: stretch;
}

.coach-emblem-panel {
  display: none;
}

.coach-emblem-art {
  display: block;
  width: min(100%, 15rem);
  aspect-ratio: 1;
  object-fit: contain;
  filter:
    drop-shadow(0 0 18px rgba(var(--coach-personal-accent-rgb), 0.2))
    drop-shadow(0 12px 26px rgba(0, 0, 0, 0.35));
}

.coach-detail-quote {
  margin: 0.4rem 0 0;
  font-family: "League Spartan", "Segoe UI", sans-serif;
  font-size: clamp(1.5rem, 4vw, 2.35rem);
  line-height: 0.96;
  color: #fff5e6;
}

.coach-detail-quote-mark {
  color: var(--accent);
}

.coach-gallery-slider {
  --coach-gallery-feature-width: 100%;
  --coach-gallery-feature-height: min(58vh, 33rem);
  --coach-gallery-dot-gap: 0.64rem;
  --coach-gallery-dot-visible: 5;
  --coach-gallery-deck-height: 5.2rem;
  --coach-gallery-featured-gap: 0.85rem;
  --coach-gallery-featured-image-height: 12.1rem;
  margin-top: 0.35rem;
  display: grid;
  justify-items: stretch;
  gap: 0.85rem;
  width: 100%;
}

.coach-gallery-slider.is-portrait {
  --coach-gallery-feature-width: min(100%, 40rem);
  --coach-gallery-feature-height: min(74vh, 46rem);
}

.coach-gallery-slider.is-landscape {
  --coach-gallery-feature-width: 100%;
  --coach-gallery-feature-height: min(56vh, 31rem);
}

.coach-gallery-slider.is-square {
  --coach-gallery-feature-width: min(100%, 44rem);
  --coach-gallery-feature-height: min(62vh, 38rem);
}

.coach-gallery-viewport {
  position: relative;
  display: flex;
  justify-content: flex-start;
  align-items: flex-start;
  overflow: hidden;
  border-radius: 24px;
  width: 100%;
  margin: 0 auto;
}

.coach-gallery-track {
  display: block;
  width: min(100%, var(--coach-gallery-feature-width));
  max-width: 100%;
  justify-self: start;
}

.coach-gallery-slide {
  margin: 0;
  width: 100%;
  display: none;
  gap: 0.72rem;
  justify-items: start;
}

.coach-gallery-slide.is-active {
  display: grid;
}

.coach-gallery-frame {
  --coach-gallery-frame-pad: clamp(0.35rem, 0.8vw, 0.65rem);
  position: relative;
  display: grid;
  place-items: center;
  overflow: hidden;
  border-radius: 24px;
  border: 1px solid rgba(255, 255, 255, 0.12);
  background:
    radial-gradient(circle at 88% 0, rgba(254, 161, 42, 0.12), transparent 36%),
    rgba(10, 10, 10, 0.92);
  box-shadow: var(--shadow-sm);
  width: min(100%, var(--coach-gallery-feature-width));
  height: var(--coach-gallery-feature-height);
  max-width: 100%;
  padding: var(--coach-gallery-frame-pad);
}

.coach-gallery-photo {
  display: block;
  object-fit: contain;
  object-position: center center;
}

.coach-gallery-frame > .coach-gallery-photo {
  position: absolute;
  inset: var(--coach-gallery-frame-pad);
  width: calc(100% - (var(--coach-gallery-frame-pad) * 2));
  height: calc(100% - (var(--coach-gallery-frame-pad) * 2));
  max-width: none;
  max-height: none;
}

.coach-gallery-caption {
  width: min(100%, var(--coach-gallery-feature-width));
  color: var(--ink-muted);
  text-align: left;
  font-size: 0.82rem;
  display: none;
}

.coach-gallery-controls {
  display: grid;
  grid-template-columns: minmax(0, 1fr);
  align-items: center;
  gap: 0.35rem;
  width: min(100%, var(--coach-gallery-feature-width));
  justify-self: start;
  min-height: var(--coach-gallery-deck-height);
}

.coach-gallery-slider.is-single .coach-gallery-controls {
  display: none;
}

.coach-gallery-nav {
  display: none;
}

.coach-gallery-featured {
  display: grid;
  gap: var(--coach-gallery-featured-gap);
  align-content: start;
  align-self: start;
  height: max-content;
}

.coach-gallery-featured-item {
  display: block;
  min-height: 0;
  padding: 0.42rem;
  border: 1px solid rgba(255, 255, 255, 0.1);
  border-radius: 18px;
  overflow: hidden;
  background:
    radial-gradient(circle at 88% 0, rgba(254, 161, 42, 0.08), transparent 34%),
    rgba(10, 10, 10, 0.82);
  box-shadow: var(--shadow-sm);
  cursor: pointer;
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.coach-gallery-featured-item:hover,
.coach-gallery-featured-item:focus-visible {
  transform: translateY(-2px);
  border-color: rgba(255, 215, 171, 0.32);
  outline: none;
}

.coach-gallery-featured-item.is-active {
  border-color: rgba(255, 201, 138, 0.52);
  box-shadow:
    0 0 0 1px rgba(255, 201, 138, 0.18),
    0 0 20px rgba(241, 89, 34, 0.14);
}

.coach-gallery-featured-item img {
  display: block;
  width: 100%;
  height: var(--coach-gallery-featured-image-height);
  object-fit: contain;
  object-position: center center;
  border-radius: 14px;
  padding: 0.32rem;
  box-sizing: border-box;
  background:
    radial-gradient(circle at 50% 24%, rgba(255, 237, 204, 0.14), transparent 54%),
    rgba(20, 16, 12, 0.9);
}

.coach-gallery-featured-item span {
  display: none;
}

.coach-gallery-featured-item--placeholder {
  display: grid;
  place-items: center;
  min-height: 0;
  border-style: dashed;
  border-color: rgba(255, 255, 255, 0.16);
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.02), rgba(255, 255, 255, 0)),
    rgba(10, 10, 10, 0.5);
  box-shadow: none;
  cursor: default;
}

.coach-gallery-featured-item--placeholder:hover,
.coach-gallery-featured-item--placeholder:focus-visible {
  transform: none;
  border-color: rgba(255, 255, 255, 0.16);
}

.coach-gallery-featured-item--placeholder span {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 100%;
  color: rgba(255, 255, 255, 0.38);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
}

@media (min-width: 980px) {
  .coach-persona-grid {
    grid-template-columns: repeat(3, minmax(0, 1fr));
  }

  .coach-style-grid {
    grid-template-columns: minmax(0, 1fr);
    align-items: stretch;
  }

  .coach-gallery-slider.is-landscape,
  .coach-gallery-slider.is-square {
    --coach-gallery-feature-width: 100%;
  }

  .coach-gallery-slider {
    --coach-gallery-dot-visible: 6;
    --coach-gallery-deck-height: 5.35rem;
    --coach-gallery-featured-image-height: 6.8rem;
    grid-template-columns: minmax(0, 1fr) 248px;
    grid-template-areas:
      "viewport featured"
      "controls featured";
    align-items: start;
    column-gap: 0.95rem;
  }

  .coach-gallery-slider.is-portrait {
    grid-template-columns: minmax(0, var(--coach-gallery-feature-width)) 248px;
    justify-content: center;
  }

  .coach-gallery-viewport {
    grid-area: viewport;
    width: 100%;
  }

  .coach-gallery-controls {
    grid-area: controls;
    width: 100%;
  }

  .coach-gallery-featured {
    grid-area: featured;
    position: static;
    width: 248px;
