    height: var(--coach-gallery-featured-image-height);
  }
}

@media (max-width: 639px) {
  .coach-persona-grid {
    grid-template-columns: minmax(0, 1fr);
  }

  .coach-style-grid {
    grid-template-columns: minmax(0, 1fr);
