  justify-content: space-between;
  gap: 0.7rem;
}

.dashboard-brand {
  font-family: "League Spartan", "Segoe UI", sans-serif;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  font-size: 1.05rem;
  color: var(--ink);
}

.dashboard-brand span {
  color: var(--accent);
}

.dashboard-topbar-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.dashboard-main {
  margin-top: 1rem;
}

.dashboard-section {
  margin-top: 1rem;
}

.crm-shell {
  width: var(--site-width);
  margin: 0 auto;
  padding: 1.6rem 0 2.2rem;
  display: grid;
  grid-template-columns: minmax(220px, 270px) minmax(0, 1fr);
  gap: 1rem;
}

.crm-sidebar {
  position: sticky;
  top: 1rem;
  align-self: start;
  border: 1px solid var(--line);
  border-radius: 22px;
  padding: 1.1rem;
  background: rgba(0, 0, 0, 0.88);
  box-shadow: var(--shadow-sm);
  display: grid;
  gap: 1rem;
}

.crm-brand {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  font-family: "League Spartan", "Segoe UI", sans-serif;
  letter-spacing: 0.06em;
  text-transform: uppercase;
  font-size: 1.25rem;
  color: var(--ink);
}

.crm-brand span {
  color: var(--accent);
}

.crm-sidebar-copy {
  color: var(--ink-muted);
  font-size: 0.9rem;
  line-height: 1.55;
}

.crm-nav {
  display: grid;
  gap: 0.35rem;
}

.crm-nav a {
  display: block;
  border: 1px solid transparent;
  border-radius: 14px;
  padding: 0.82rem 0.9rem;
  color: var(--ink);
  background: rgba(255, 255, 255, 0.04);
  font-family: "Montserrat", "Segoe UI", sans-serif;
  letter-spacing: 0.03em;
  transition: transform 0.2s ease, border-color 0.2s ease, background 0.2s ease, color 0.2s ease;
}

.crm-nav a:hover,
.crm-nav a:focus-visible {
  transform: translateX(3px);
  border-color: rgba(241, 89, 34, 0.35);
  background: rgba(241, 89, 34, 0.12);
  color: #fff;
}

.crm-nav a.is-current {
  border-color: rgba(241, 89, 34, 0.55);
  background: linear-gradient(135deg, rgba(241, 89, 34, 0.22), rgba(255, 255, 255, 0.08));
  color: #fff;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.crm-sidebar-footer {
  display: grid;
  gap: 0.55rem;
}

.crm-sidebar--client,
.crm-sidebar--coach {
  background:
    linear-gradient(180deg, rgba(8, 8, 8, 0.94), rgba(8, 8, 8, 0.82)),
    rgba(0, 0, 0, 0.88);
}

.crm-content {
  min-width: 0;
}

.crm-page-head {
  border: 1px solid var(--line);
  border-radius: 22px;
  padding: 1.15rem;
  background: rgba(0, 0, 0, 0.84);
  box-shadow: var(--shadow-sm);
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: flex-start;
}

.crm-page-head p {
  color: var(--ink-muted);
}

.crm-page-meta {
  display: grid;
  gap: 0.4rem;
  justify-items: end;
  text-align: right;
}

.crm-page-meta strong {
  color: var(--ink);
}

.crm-section-grid {
  display: grid;
  gap: 1rem;
}

.crm-callout {
  border: 1px solid rgba(241, 89, 34, 0.28);
  border-radius: 16px;
  padding: 0.95rem;
  background: rgba(241, 89, 34, 0.08);
}

.crm-callout p {
  color: var(--ink-muted);
}

.dashboard-table-wrap {
  margin-top: 0.75rem;
  overflow-x: auto;
}

.dashboard-table {
  width: 100%;
  border-collapse: collapse;
  border: 1px solid var(--line);
  border-radius: 12px;
  overflow: hidden;
}

.dashboard-table th,
.dashboard-table td {
  padding: 0.72rem 0.76rem;
  text-align: left;
  border-bottom: 1px solid rgba(255, 255, 255, 0.12);
  color: var(--ink);
}

.dashboard-table th {
  background: rgba(255, 255, 255, 0.06);
  font-size: 0.8rem;
  text-transform: uppercase;
  letter-spacing: 0.04em;
  font-family: "Montserrat", "Segoe UI", sans-serif;
  color: var(--accent);
}

.dashboard-list {
  margin-top: 0.7rem;
  padding-left: 1rem;
  color: var(--ink-muted);
}

.dashboard-list li {
  margin-bottom: 0.38rem;
}

.dashboard-note-log {
  margin-top: 0.75rem;
  display: grid;
  gap: 0.52rem;
}

.dashboard-note {
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 0.72rem;
  background: rgba(255, 255, 255, 0.04);
}

.dashboard-note p {
  color: var(--ink);
}

.dashboard-note small {
  color: var(--ink-muted);
}

.dashboard-avatar-card {
  display: grid;
  gap: 0.7rem;
}

.dashboard-avatar {
  width: 78px;
  height: 78px;
  border-radius: 999px;
  display: grid;
  place-items: center;
  font-family: "League Spartan", "Segoe UI", sans-serif;
  font-size: 1.5rem;
  background: linear-gradient(135deg, var(--primary), var(--accent));
  color: #fff;
  box-shadow: 0 10px 22px rgba(241, 89, 34, 0.26);
}

.dashboard-badge-grid {
  margin-top: 0.75rem;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(170px, 1fr));
  gap: 0.65rem;
}

.dashboard-badge {
  border: 1px solid var(--line);
  border-radius: 12px;
  padding: 0.72rem;
  background: rgba(255, 255, 255, 0.04);
}

.dashboard-badge strong {
  color: var(--accent);
  font-family: "Montserrat", "Segoe UI", sans-serif;
  text-transform: uppercase;
  letter-spacing: 0.03em;
  font-size: 0.76rem;
}

.dashboard-badge p {
  margin-top: 0.28rem;
  color: var(--ink);
}

.dashboard-card-grid {
  margin-top: 0.85rem;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: 0.8rem;
}

.dashboard-card-grid--packages {
  grid-template-columns: repeat(auto-fit, minmax(290px, 1fr));
}

.package-card {
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 1rem;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.02)),
    rgba(0, 0, 0, 0.52);
  box-shadow: var(--shadow-sm);
  display: grid;
  gap: 0.8rem;
}

.package-card--owned {
  background:
    linear-gradient(180deg, rgba(241, 89, 34, 0.09), rgba(255, 255, 255, 0.02)),
    rgba(0, 0, 0, 0.56);
}

.package-card--selected {
  border-color: rgba(241, 89, 34, 0.5);
  box-shadow:
    0 16px 32px rgba(241, 89, 34, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.package-card__top {
  display: flex;
  justify-content: space-between;
  gap: 1rem;
  align-items: flex-start;
}

.package-card__title {
  margin-top: 0.25rem;
  font-size: 1.05rem;
}

.package-card__price {
  white-space: nowrap;
  color: var(--accent);
  font-family: "Montserrat", "Segoe UI", sans-serif;
  letter-spacing: 0.02em;
}

.package-card__copy {
  color: var(--ink-muted);
  line-height: 1.6;
  font-size: 0.92rem;
}

.package-card__stats {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.7rem;
}

.package-card__stats div {
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 12px;
  padding: 0.7rem;
  background: rgba(255, 255, 255, 0.04);
}

.package-card__stats dt {
  font-size: 0.72rem;
  text-transform: uppercase;
  letter-spacing: 0.06em;
  color: var(--ink-muted);
  font-family: "Montserrat", "Segoe UI", sans-serif;
}

.package-card__stats dd {
  margin-top: 0.35rem;
  color: var(--ink);
  font-weight: 700;
}

.dashboard-feedback {
  margin-top: 0.62rem;
  color: var(--ink-muted);
  font-size: 0.88rem;
}

.dashboard-feedback.error {
  color: #ffb8a0;
}

.dashboard-feedback.success {
  color: #b3f5d8;
}

.admin-lock {
  margin-top: 1rem;
  border: 1px solid rgba(241, 89, 34, 0.48);
  border-radius: 16px;
  padding: 1rem;
  background: rgba(241, 89, 34, 0.08);
}

.funnel-grid {
  margin-top: 0.75rem;
  display: grid;
  gap: 0.7rem;
}

.funnel-column {
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 0.8rem;
  background: rgba(255, 255, 255, 0.04);
}

.funnel-column h3 {
  font-size: 1rem;
}

.account-quick-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(220px, 1fr));
  gap: 0.8rem;
}

.account-quick-card {
  border: 1px solid var(--line);
  border-radius: 16px;
  padding: 1rem;
  background:
    linear-gradient(160deg, rgba(241, 89, 34, 0.14), rgba(255, 255, 255, 0.04)),
    rgba(0, 0, 0, 0.52);
  box-shadow: var(--shadow-sm);
  display: grid;
  gap: 0.55rem;
}

.account-quick-card h3 {
  font-size: 1rem;
}

.account-quick-card p {
  color: var(--ink-muted);
  margin: 0;
}

.account-settings-grid {
  display: grid;
  gap: 1rem;
}

.account-settings-grid__wide {
  grid-column: 1 / -1;
}

.account-meta-list {
  display: grid;
  gap: 0.7rem;
  margin-top: 0.85rem;
}

.account-meta-item {
  border: 1px solid var(--line);
  border-radius: 14px;
  padding: 0.85rem 0.95rem;
  background: rgba(255, 255, 255, 0.04);
}

.account-meta-item strong {
  display: block;
  font-family: "Montserrat", "Segoe UI", sans-serif;
  font-size: 0.82rem;
  text-transform: uppercase;
  letter-spacing: 0.05em;
  color: var(--accent);
}

.account-meta-item span {
  display: block;
  margin-top: 0.26rem;
  color: var(--ink);
}

.account-security-form {
  display: grid;
  gap: 1rem;
  margin-top: 1rem;
}

.account-security-form .section-actions {
  flex-wrap: wrap;
  gap: 0.75rem;
}

.account-security-form .btn {
  min-width: 12rem;
}

.wearable-sync-shell {
  display: grid;
  gap: 1rem;
}

.wearable-sync-grid {
  display: grid;
  grid-template-columns: minmax(320px, 1.08fr) minmax(260px, 0.92fr);
  gap: 1rem;
  align-items: start;
}

.wearable-provider-list {
  display: grid;
  gap: 0.85rem;
}

.wearable-provider-card {
  display: grid;
  gap: 0.8rem;
  min-width: 0;
  padding: 1rem 1.05rem;
  border-radius: 22px;
  border: 1px solid rgba(255, 215, 170, 0.14);
  background:
    radial-gradient(circle at 86% 14%, rgba(255, 167, 85, 0.1), transparent 24%),
    linear-gradient(155deg, rgba(34, 21, 16, 0.96), rgba(13, 9, 8, 0.985));
  box-shadow:
    0 20px 40px rgba(0, 0, 0, 0.24),
    inset 0 1px 0 rgba(255, 255, 255, 0.04);
}

.wearable-provider-card--featured {
  gap: 0.95rem;
}

.wearable-provider-card__head {
  display: flex;
  align-items: start;
  justify-content: space-between;
  gap: 0.9rem;
}

.wearable-provider-card__head h3 {
  margin: 0.16rem 0 0;
}

.wearable-provider-card p {
  margin: 0;
  color: rgba(242, 222, 199, 0.82);
  line-height: 1.62;
}

.wearable-chip-row {
  justify-content: flex-end;
}

.wearable-provider-card__stats {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 0.8rem;
  margin: 0;
}

.wearable-provider-card__stats div,
.wearable-summary-item {
  display: grid;
  align-content: start;
  gap: 0.38rem;
  padding: 0.82rem 0.88rem;
  border-radius: 18px;
  border: 1px solid rgba(255, 224, 191, 0.12);
  background: rgba(11, 8, 7, 0.42);
}

.wearable-provider-card__stats dt,
.wearable-summary-item span {
  color: rgba(255, 236, 206, 0.72);
  font-size: 0.72rem;
  font-weight: 800;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.wearable-provider-card__stats dd,
.wearable-summary-item strong {
  display: block;
  margin: 0;
  color: var(--crm-theme-text-0);
  font-family: "League Spartan", "Montserrat", sans-serif;
  font-size: clamp(1.1rem, 1.6vw, 1.42rem);
  line-height: 1.02;
}

.wearable-summary-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 0.85rem;
}

.wearable-summary-item p {
  margin: 0;
  color: rgba(242, 222, 199, 0.78);
  font-size: 0.88rem;
  line-height: 1.56;
}

@media (max-width: 1080px) {
  .wearable-sync-grid,
  .wearable-summary-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 640px) {
  .wearable-provider-card {
    padding: 0.95rem;
  }

  .wearable-provider-card__head {
    flex-direction: column;
    align-items: flex-start;
  }

  .wearable-chip-row {
    justify-content: flex-start;
  }

  .wearable-provider-card__stats {
    grid-template-columns: 1fr;
  }
}

.section-actions--compact {
  display: flex;
  flex-wrap: wrap;
  gap: 0.45rem;
}

.section-actions--compact .btn {
  min-width: 0;
  padding: 0.58rem 0.78rem;
}

.appearance-grid {
  margin-top: 0.85rem;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 0.85rem;
}

.appearance-card {
  border: 1px solid rgba(255, 255, 255, 0.12);
  border-radius: 18px;
  padding: 0;
  overflow: hidden;
  text-align: left;
  background: rgba(255, 255, 255, 0.04);
  color: var(--ink);
  cursor: pointer;
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.appearance-card:hover,
.appearance-card:focus-visible {
  transform: translateY(-2px);
  border-color: rgba(241, 89, 34, 0.42);
  box-shadow: 0 14px 28px rgba(241, 89, 34, 0.12);
}

.appearance-card.is-active {
  border-color: rgba(241, 89, 34, 0.72);
  background:
    linear-gradient(180deg, rgba(241, 89, 34, 0.18), rgba(255, 255, 255, 0.04)),
    rgba(255, 255, 255, 0.04);
  box-shadow:
    0 18px 34px rgba(241, 89, 34, 0.16),
    inset 0 1px 0 rgba(255, 255, 255, 0.08);
}

.appearance-card__media {
  display: block;
  aspect-ratio: 16 / 10;
  background-size: cover;
  background-position: center;
}

.appearance-card__body {
  display: grid;
  gap: 0.26rem;
  padding: 0.9rem 0.95rem 1rem;
}

.appearance-card__body strong {
  font-family: "Montserrat", "Segoe UI", sans-serif;
  font-size: 0.9rem;
  letter-spacing: 0.03em;
}

.appearance-card__body span {
  color: var(--ink-muted);
  font-size: 0.84rem;
}

.lead-filter-bar {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: 0.75rem;
  margin-top: 0.8rem;
}

.lead-filter-bar label {
  display: grid;
  gap: 0.42rem;
  min-width: 0;
  color: var(--ink);
  font-family: "Montserrat", "Segoe UI", sans-serif;
  font-size: 0.92rem;
  font-weight: 700;
}

.lead-filter-bar :is(input, select) {
  width: 100%;
  min-width: 0;
  border-radius: 18px;
  border: 1px solid rgba(255, 198, 107, 0.2);
  background:
    linear-gradient(180deg, rgba(255, 181, 91, 0.06), rgba(255, 114, 43, 0.02)),
    rgba(20, 10, 7, 0.88);
  color: var(--ink);
  padding: 0.9rem 1rem;
  font: inherit;
  box-shadow: inset 0 1px 0 rgba(255, 240, 207, 0.04);
}

.lead-filter-bar :is(input, select)::placeholder {
  color: rgba(236, 213, 184, 0.68);
}

.lead-filter-bar :is(input, select):focus-visible {
  outline: none;
  border-color: rgba(255, 197, 98, 0.48);
  box-shadow:
    0 0 0 1px rgba(255, 197, 98, 0.16),
    0 0 0 6px rgba(255, 161, 74, 0.08);
}

.lead-board {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(280px, 1fr));
  gap: 1rem;
  margin-top: 0.9rem;
  align-items: start;
}

.lead-board__column {
  border: 1px solid var(--line);
  border-radius: 18px;
  padding: 0.95rem;
  background:
    linear-gradient(180deg, rgba(255, 255, 255, 0.05), rgba(255, 255, 255, 0.02)),
    rgba(0, 0, 0, 0.46);
  display: grid;
  gap: 0.75rem;
  min-width: 0;
}

.lead-board__head {
  display: flex;
  justify-content: space-between;
  gap: 0.65rem;
  align-items: baseline;
}

.lead-board__head h3 {
  font-size: 0.95rem;
}

.lead-board__count {
  font-family: "Montserrat", "Segoe UI", sans-serif;
  color: var(--accent);
  font-size: 0.84rem;
}

.lead-board__stack {
  display: grid;
  gap: 0.65rem;
}

.lead-board__empty {
  color: var(--ink-muted);
  font-size: 0.84rem;
}

.lead-chip-card {
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 14px;
  padding: 0.82rem;
  background: rgba(255, 255, 255, 0.04);
  display: grid;
  gap: 0.4rem;
  min-width: 0;
  overflow: hidden;
}

.lead-chip-card strong {
  font-size: 0.95rem;
  display: block;
  min-width: 0;
  overflow-wrap: anywhere;
}

.lead-chip-card p,
.lead-chip-card small {
  margin: 0;
  color: var(--ink-muted);
  min-width: 0;
  overflow-wrap: anywhere;
}

.lead-chip-card__meta {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  min-width: 0;
}

.lead-chip-card__meta .chip {
  max-width: 100%;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.lead-chip-card__contact {
  font-size: 0.92rem;
}

.lead-chip-card__follow-up {
  color: rgba(255, 234, 210, 0.84);
}

body[data-live-dashboard] {
  overflow-x: hidden;
  --crm-theme-bg-0: #080706;
  --crm-theme-bg-1: #120d0b;
  --crm-theme-bg-2: #1e1713;
  --crm-theme-surface: rgba(20, 15, 12, 0.88);
  --crm-theme-surface-alt: rgba(31, 23, 18, 0.94);
  --crm-theme-surface-strong: rgba(12, 9, 8, 0.98);
  --crm-theme-surface-border: rgba(175, 125, 70, 0.24);
  --crm-theme-surface-border-strong: rgba(217, 171, 106, 0.48);
  --crm-theme-highlight: rgba(255, 244, 213, 0.04);
  --crm-theme-text-0: #fff7ea;
  --crm-theme-text-1: #f2dec7;
  --crm-theme-text-2: #c49a73;
  --tone-alert: #b15d43;
  --tone-alert-soft: rgba(177, 93, 67, 0.18);
  --tone-warning: #c0a056;
  --tone-warning-soft: rgba(192, 160, 86, 0.18);
  --tone-info: #6e8ca4;
  --tone-info-soft: rgba(110, 140, 164, 0.18);
  --tone-success: #6c9471;
  --tone-success-soft: rgba(108, 148, 113, 0.18);
  --tone-neutral: #877163;
  --tone-neutral-soft: rgba(135, 113, 99, 0.16);
  --crm-gradient-fire: linear-gradient(135deg, #9c2d11 0%, #cf461c 24%, #ff8b1f 60%, #f5c73b 100%);
  --crm-gradient-auric: linear-gradient(125deg, #fff7d4 0%, #ebc967 18%, #be8520 46%, #ffe59a 74%, #865410 100%);
  --crm-gradient-page:
    radial-gradient(circle at top left, rgba(153, 83, 34, 0.24), transparent 28%),
    radial-gradient(circle at top right, rgba(210, 163, 92, 0.12), transparent 22%),
    radial-gradient(circle at 78% 16%, rgba(103, 64, 35, 0.16), transparent 18%),
    radial-gradient(circle at bottom center, rgba(92, 59, 28, 0.12), transparent 30%),
    linear-gradient(180deg, #060505 0%, #0d0a08 30%, #18120f 100%);
  --crm-shell-bg: var(--crm-theme-surface-strong);
  --crm-shell-bg-soft: var(--crm-theme-surface);
  --crm-shell-bg-contrast: var(--crm-theme-surface-alt);
  --crm-shell-line: var(--crm-theme-surface-border);
  --crm-shell-line-strong: var(--crm-theme-surface-border-strong);
  --crm-shell-shadow: 0 24px 56px rgba(0, 0, 0, 0.42), inset 0 1px 0 rgba(255, 245, 215, 0.03);
  --crm-shell-shadow-glow: 0 18px 42px rgba(112, 68, 34, 0.18), 0 0 48px rgba(160, 118, 63, 0.08);
  --crm-surface-glass:
    linear-gradient(180deg, rgba(255, 255, 255, 0.02), transparent 60%),
    linear-gradient(150deg, rgba(147, 94, 45, 0.1), transparent 42%),
